import { CommonModule } from '@angular/common';
import { booleanAttribute, ChangeDetectorRef, Component, Inject, Input } from '@angular/core';
import { IconComponent } from '../icon/icon.component';
import { AvatarComponent } from '../avatar/avatar.component';
import { MatMenuModule } from '@angular/material/menu';
import { MatTooltipModule } from '@angular/material/tooltip';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { Router, RouterLink } from '@angular/router';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { LogoutService } from '../../../core/services/logout/logout.service';
import { HttpClientModule } from '@angular/common/http';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { HeaderService } from '../../../core/services/header/header.service';
import { UsercreationComponent } from '../../../adminpanel/components/casebuilder/usercreation/usercreation.component';
import { environment } from '../../../../environments/environment';

@Component({
  selector: 'profile',
  standalone: true,
  providers: [LogoutService],
  imports: [CommonModule, IconComponent, AvatarComponent, MatMenuModule, MatTooltipModule, HttpClientModule, MatDialogModule, RouterLink],
  templateUrl: './profile.component.html',
  styleUrl: './profile.component.scss'
})
export class ProfileComponent {
  isLegal: boolean = ['T', 'M', 'D'].includes(environment.als)
  @Input() size: string = 'sm';
  @Input() detail: any;
  @Input({ transform: booleanAttribute }) icon: boolean = true;
  @Input({ transform: booleanAttribute }) showname: boolean = false;
  @Input() userguidebtn: boolean = true;
  @Input() iconwhite: boolean = false;
  @Input() isdark: boolean = false;
  @Input() type: any = 'admin';
  @Input() gap: any = '';
  @Input() addcls: string = '';
  // private uDash: UserdashboardService,
  constructor(public ss: SecureStorageService, public hs: HeaderService, public cf: CommonfunctionService,
    private logout: LogoutService, private dialog: MatDialog, public router: Router, private cdr: ChangeDetectorRef,
  ) {

  }

  ngOnInit(): void {
    //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
    //Add 'implements OnInit' to the class.
  }

  async logOut() {
    await this.logout.logout()
    this.ss.logOut();
    this.cf.goto('/auth/login');
  }


  get addClasses() {
    return `${this.addcls} || ''}`;
  }

  accountSetting() {
    var data = {
      nCaseid: this.hs.Casedetail.nCaseid,
      nUserid: this.detail.nUserid,
      ismyfiles: true
    }
    const dialogRef = this.dialog.open(UsercreationComponent, {
      width: '678px',
      height: 'fit-content',
      maxHeight: '99vh',
      panelClass: ['addusermodal', 'rounded-10', 'overflow-hidden'],
      backdropClass: 'profilebackdrop',
      data: data,
      position: {
        top: '58px',
        right: '10px'
      }
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result && result.isSave) {
        debugger
        this.detail.cProfile = result.cProfile || this.detail.cProfile;
        this.detail.cFname = result.cFname || this.detail.cFname;
        this.detail.cLname = result.cLname || this.detail.cLname;
        this.ss.setUserInfo(this.detail, 0);
        this.cdr.detectChanges();
      }

    })
  }

  helpcenter() {
    this.cf.goto('/helpcenter');
  }
  helpcenteradmin() {
    this.cf.goto('/helpcenteradmin');
  }


  openInNewTab(route: string, param: string): void {
    const url = this.router.serializeUrl(
      this.router.createUrlTree([route, param])
    );
    window.open(url, '_blank');
  }


  transcript() {
    this.cf.goto('/transcript')
  }
}
